followup_test_patch:
--- src/tests/core_words_test.zig
+++ candidate/src/tests/core_words_test.zig
@@ -997,3 +997,90 @@
     );
     try expectOutput("STRUCT CELL% FIELD S.A END-STRUCT R% HERE 1 ALLOT R% %ALIGN HERE SWAP - . HERE R% %ALLOT TUCK = . HERE SWAP - . R% %ALLOC 0<> . R% %ALLOCATE . 0<> .", "8 -1 8 -1 0 -1 ");
 }
+
+
+test "two R fetch preserves boundary states error priority and compiled PC" {
+    for ([_]bool{ false, true }) |counted| {
+        for ([_]bool{ false, true }) |compiled| {
+            for ([_]bool{ false, true }) |pending| {
+                for ([_]usize{ 0, 1, 2, 5 }) |ret_depth| {
+                    for ([_]usize{ 0, 1, 2, 5 }) |space| {
+                        var output = Output{};
+                        const machine = try createMachine(&output);
+                        defer destroyMachine(machine);
+                        machine.keep_counting = counted;
+                        try machine.interpretLine(": CHECK-2RF 2R@ ;");
+                        const id = try machine.lookupOrFail("CHECK-2RF");
+                        const caller = machine.words[id];
+                        const depth = machine.data_stack.len - space;
+                        for (0..depth) |i| machine.data_stack[i] = @as(forth.Cell, @intCast(i)) - 17;
+                        machine.data_depth = depth;
+                        @memset(machine.data_stack[depth..], -919);
+                        for (0..ret_depth) |i| machine.return_stack[i] = if (i % 2 == 0) std.math.minInt(forth.Cell) else std.math.maxInt(forth.Cell);
+                        machine.return_depth = ret_depth;
+                        if (pending) machine.output_error = -123;
+                        const result = if (compiled) machine.executeWord(id) else machine.executeBuiltin(.two_r_fetch);
+                        if (pending) {
+                            try std.testing.expectError(error.Thrown, result);
+                            try std.testing.expectEqual(@as(forth.Cell, -123), machine.throw_code);
+                        } else if (ret_depth < 2) {
+                            try std.testing.expectError(error.ReturnStackUnderflow, result);
+                        } else if (space < 2) {
+                            try std.testing.expectError(error.StackOverflow, result);
+                        } else try result;
+                        const success = ret_depth >= 2 and space >= 2;
+                        try std.testing.expectEqual(depth + @as(usize, if (success) 2 else 0), machine.data_depth);
+                        for (0..depth) |i| try std.testing.expectEqual(@as(forth.Cell, @intCast(i)) - 17, machine.data_stack[i]);
+                        if (!success) for (machine.data_stack[depth..]) |cell| try std.testing.expectEqual(@as(forth.Cell, -919), cell);
+                        if (success) try std.testing.expectEqualSlices(forth.Cell, machine.return_stack[ret_depth - 2 .. ret_depth], machine.data_stack[depth .. depth + 2]);
+                        try std.testing.expectEqual(ret_depth, machine.return_depth);
+                        for (0..ret_depth) |i| try std.testing.expectEqual(@as(forth.Cell, if (i % 2 == 0) std.math.minInt(forth.Cell) else std.math.maxInt(forth.Cell)), machine.return_stack[i]);
+                        try std.testing.expect(machine.output_error == null);
+                        if (@import("../core/defs.zig").debug_enabled and compiled and (pending or !success)) {
+                            try std.testing.expectEqual(caller.code_start + 1, machine.failed_pc);
+                            try std.testing.expect(machine.backtrace_count != 0);
+                            try std.testing.expectEqual(caller.code_start, machine.backtrace[0]);
+                        }
+                        try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
+                        try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
+                    }
+                }
+            }
+        }
+    }
+}
+
+
+test "two R fetch catches boundary errors and restores both stacks" {
+    for ([_]bool{ false, true }) |counted| {
+        for ([_]usize{ 0, 1, 2 }) |ret_depth| {
+            for ([_]usize{ 0, 3 }) |depth| {
+                var output = Output{};
+                const machine = try createMachine(&output);
+                defer destroyMachine(machine);
+                machine.keep_counting = counted;
+                try machine.interpretLine(": CATCH-2RF 2R@ ;");
+                const storage = machine.data_stack;
+                defer machine.data_stack = storage;
+                machine.data_stack = storage[0..4];
+                for (0..depth) |i| try machine.push(@as(forth.Cell, @intCast(51 + i)));
+                machine.return_depth = ret_depth;
+                for (0..ret_depth) |i| machine.return_stack[i] = @as(forth.Cell, @intCast(71 + i));
+                try machine.interpretLine("' CATCH-2RF CATCH");
+                const code = try machine.pop();
+                try std.testing.expectEqual(@as(forth.Cell, if (ret_depth < 2) -6 else if (depth == 3) -3 else 0), code);
+                if (ret_depth == 2 and depth == 0) {
+                    try expectStack(machine, &.{ 71, 72 });
+                } else {
+                    try std.testing.expectEqual(depth, machine.data_depth);
+                    for (0..depth) |i| try std.testing.expectEqual(@as(forth.Cell, @intCast(51 + i)), machine.data_stack[i]);
+                }
+                try std.testing.expectEqual(ret_depth, machine.return_depth);
+                for (0..ret_depth) |i| try std.testing.expectEqual(@as(forth.Cell, @intCast(71 + i)), machine.return_stack[i]);
+                try std.testing.expectEqual(@as(usize, 0), machine.catch_depth);
+                try std.testing.expectEqual(@as(usize, 0), machine.frame_depth);
+                try std.testing.expectEqual(@as(usize, 0), machine.call_depth);
+            }
+        }
+    }
+}
